Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include<bits/stdc++.h>
using namespace std;

#define LL long long int
#define ULL unsigned LL
#define PII pair<int,int>
#define PB push_back
#define MP make_pair
#define INF 1000000000
#define MOD 1000000007

int shortest[15][15][15][15];
int cap[400][400];
char scien[20][20];
char reac[20][20];
int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};
int iter = 3;
int vis[400];

int n, t;
int aug(int cnode, int dest, int bneck) {
    if (cnode == dest) {
        return bneck;
    }
    if (vis[cnode] == iter) {
        return 0;
    }
    vis[cnode] = iter;
    for (int i = 0; i <= dest; i++) {
        int cret = 0;
        if (cap[cnode][i] > 0 && (cret = aug(i, dest, min(bneck, cap[cnode][i])))) {
            // cout << cnode << " ";
            cap[cnode][i] -= cret;
            cap[i][cnode] += cret;
            return cret;
        }
    }
    return 0;
}
int getnode(int x, int y) {
    return (x - 1) * n + y - 1;
}
int reach[13][13];
int treach[13][13];
void expand(int val) {
    int i, j, k;
    for (i = 1; i <= n; i++)
        for (j = 1; j <=n; j++)
            treach[i][j] = reach[i][j];
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            if (treach[i][j] == val) {
                for (k = 0; k < 4; k++) {
                    int ni = i + dx[k];
                    int nj = j + dy[k];
                    if (ni > 0 && nj > 0 && ni <= n && nj <= n && treach[ni][nj] < val && scien[ni][nj] != 'Y') {
                        reach[ni][nj] = val;
                    }
                }
            }
        }
    }
}
bool canreach(int sx, int sy, int tx, int ty, int ix, int iy) {
    memset(reach, 0, sizeof(reach));
    reach[sx][sy] = 1;
    reach[ix][iy] = 2;
    int iters = 100;
    while (iters--) {
        expand(1);
        if (reach[tx][ty] == 1)
            return true;
        expand(2);
        if (reach[tx][ty] == 2)
            return false; 
    }
    return false;
}
int main() {
    int infx, infy;
    memset(shortest, 1, sizeof(shortest));
    cin >> n >> t;
    int i, j;
    for (i = 1; i <= n; i++) {
        scanf(" %s", scien[i] + 1);
        for (j = 1; j <= n; j++) {
            shortest[i][j][i][j] = 0;
            if (scien[i][j] == 'Z') {
                infx = i;
                infy = j;
            }
        }
    }
    for (i = 1; i <= n; i++) {
        scanf(" %s", reac[i] + 1);
    }
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            for (int k = 0; k < 4; k++) {
                int ni = i + dx[k];
                int nj = j + dy[k];
                if (ni <= n && ni > 0 && nj <= n && nj > 0) {
                    if (scien[i][j] != 'Y' && scien[ni][nj] != 'Y')
                        shortest[i][j][ni][nj] = 1;
                }
            }
        }
    }
    int ki, kj, ii, ij, ji, jj;
    for (ki = 1; ki <= n; ki++) {
        for (kj = 1; kj <= n; kj++) {
            for (ii = 1; ii <= n; ii++) {
                for (ij = 1; ij <= n; ij++) {
                    for (ji = 1; ji <= n; ji++) {
                        for (jj = 1; jj <= n; jj++) {
                            shortest[ii][ij][ji][jj] = min(
                                    shortest[ii][ij][ji][jj], 
                                    shortest[ii][ij][ki][kj] + shortest[ki][kj][ji][jj]
                                    );
                        }
                    }
                }
            }
        }
    }
    int src = n * n * 2 + 1;
    int dest = n * n * 2 + 2;
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            if (isdigit(scien[i][j])) {
                cap[src][getnode(i, j)] = scien[i][j] - '0';
            }
            if (isdigit(reac[i][j])) {
                cap[n * n + getnode(i, j)][dest] = reac[i][j] - '0';
            }

            if (isdigit(scien[i][j])) {
                for (ki = 1; ki <= n; ki++) {
                    for (kj = 1; kj <= n; kj++) {
                        if (scien[i][j] > '0' && reac[ki][kj] > '0') {
                            if (isdigit(reac[ki][kj]) && shortest[i][j][ki][kj] <= t && canreach(i, j, ki, kj, infx, infy)) {
                                // printf("(%d, %d) can reach (%d, %d)\n", i, j, ki, kj);
                                cap[getnode(i, j)][n * n + getnode(ki, kj)] = 1000;
                            }
                        }
                    }
                }
            }
        }
    }
    int mflow = 0, ret;
    while ((ret = aug(src, dest, 1000))) {
        // cout << endl;
        mflow += ret;
        iter ++;
    }
    cout << mflow << endl;
    return 0;
}


